INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 14, 'theory', 'Quiz: segment trees and Fenwick trees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 0, 'Which range does cell number 12 store in a Fenwick tree (numbering from one)?', '["Elements 1 through 12", "Only element 12", "Elements 9 through 12: the length equals the lowest set bit of 12, which is four", "Elements 6 through 12"]', 2, '12 in binary is 1100, and the lowest set bit is 4. The cell stores the sum of a range of length 4 ending at 12: elements 9, 10, 11 and 12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 1, 'How do you find the sum of the first 11 elements in a Fenwick tree?', '["Add up cells 1, 2, …, 11", "Take cell 11 and multiply by 11", "Add cells 11, 12 and 16: at each step we add the lowest bit", "Add cells 11, 10 and 8: at each step we clear the lowest bit of the index"]', 3, '11 = 1011₂ → 10 = 1010₂ → 8 = 1000₂ → 0: cells 11, 10 and 8 cover elements 11, 9–10 and 1–8, which is exactly the first eleven.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 2, 'Which requirement on the operation distinguishes the segment tree from the Fenwick tree for a minimum query?', '["The segment tree needs an invertible operation, Fenwick works with any", "A minimum cannot be computed in a tree; it only suits sums", "Fenwick works for the minimum, but the segment tree does not", "The minimum is not invertible (you cannot \"subtract\" a prefix from a prefix minimum), so the segment tree fits"]', 3, 'Fenwick gets a range by subtracting two prefixes, and for the minimum there is no such subtraction. The segment tree does not subtract; it combines ready-made nodes, so associativity is enough.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 3, 'Why do we need lazy tags in a segment tree?', '["To save memory on the leaves", "To change a whole range in a logarithm of time, postponing the children''s update until we descend", "To keep copies of the array for rollback", "To speed up building the tree to linear time"]', 1, 'A node fully covered by the change is updated at once, and the children are left with a debt tag. It is pushed down only when we descend, so a range operation does not turn into a walk over all the elements.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 4, 'Why can a sparse table answer a minimum query in constant time, but not a sum?', '["For sums the table needs more memory than for minimums", "The minimum is computed faster than the sum on any processor", "Two overlapping ranges of length 2ᵏ are fine for the minimum (it is idempotent), but for a sum the overlap would be counted twice", "The table stores only minimums and by construction cannot do sums"]', 2, 'min(x, x) = x, so overlapping two powers of two does not spoil the answer. For a sum the overlapping part would be counted twice, so the range would have to be split without overlap, and that is already a logarithm.');
